"""Publish the recovery explanation acceptance without changing retained business records."""
import html,json,shutil
from pathlib import Path
from datetime import datetime
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/purchase-return-restore-review'

def main():
 a=json.loads((OUT/'acceptance.json').read_text('utf-8'));tests=json.loads((ROOT/'outputs/purchase-return-fulfillment/regression.json').read_text('utf-8'));assert a['result']=='PASS' and a['before']==a['after']
 q=json.loads((OUT/'query-check.json').read_text('utf-8'));assert q['result']=='PASS' and q['current_run_baseline_unchanged']
 c=a['source_check'];l=c['lines'][0];other=l['claimants'][0];esc=lambda v:html.escape(str(v))
 def link(id,label):return '<a href="/oms-supplychain/purchaseReturns?id='+str(id)+'">'+esc(label)+'</a>'
 css="body{margin:0;background:#f2f6fb;color:#34445b;font:15px/1.8 'Microsoft YaHei',sans-serif}main{max-width:1380px;margin:28px auto;background:white;padding:30px;border-radius:10px}h1{font-size:25px}h2{font-size:20px;margin-top:28px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.metrics article{background:#eff5fd;border-radius:8px;padding:20px}.metrics span,.metrics b{display:block}.metrics b{font-size:27px;margin-top:8px}.short{color:#b65c19}.muted{color:#7a899d;font-size:13px}.notice{padding:17px;background:#fff8e8;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:14px;margin:18px 0}td,th{border:1px solid #dfe7f1;text-align:left;padding:12px}th{background:#f3f7fc}a{color:#0877dc;overflow-wrap:anywhere}img{display:block;max-width:100%;border:1px solid #dfe7f1;margin:15px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f6fa;padding:16px;font-size:12px}summary{cursor:pointer;color:#0877dc}"
 parts=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>采购退仓恢复额度核对优化验收</title><style>'+css+'</style><main><h1>采购退仓恢复额度：缺口与占用单据核对</h1><p class="muted">'+datetime.now().isoformat()+' · 使用原保留TEST单据只读验收</p><p>'+link(c['return_id'],c['return_sn'])+'</p><div class="metrics"><article><span>本次申请恢复</span><b>3 件</b></article><article><span>来源及批次可恢复</span><b>1 件</b></article><article><span>本次缺口</span><b class="short">2 件</b></article></div><h2>实际原因与处理入口</h2><table><tr><th>原来源实收</th><th>本单已退</th><th>其他退仓已用 / 占用</th><th>原来源余额</th><th>原批次可用</th></tr><tr><td>10 件</td><td>2 件</td><td>7 件</td><td>1 件</td><td>1 件</td></tr></table><p>原来源余额：10 − 2 − 7 = 1 件。本次仍按原申请的3件整体核对，当前缺2件。</p><p>占用单据：'+link(other['return_id'],other['return_sn'])+'，仓库已受理，实出已扣0件，未出计划7件。如优先恢复本单，先协调该单的未出计划，等待仓库确认停止与释放后，再返回原单刷新核对并审核。</p><h2>已完成的界面与校验调整</h2><ul><li>点击审核先打开核对窗口，展示原来源、本单已退、其他单已用/计划占用、余额、需恢复和缺口。</li><li>占用单号支持在新标签页查看与处理；返回原窗口可主动刷新额度及库存。</li><li>原来源额度和批次库存分别核查，多个来源共用同一批次时合并库存需求，避免重复计算可用量。</li><li>额度或库存不满足时禁用审核；库存查询未确认时显示待确认，保留刷新入口。</li><li>提交时仍在原采购与业务单锁内再次校验来源，变更时返回最新结构化缺口。</li><li>恢复核对及审核由窗口统一显示错误，修复接口层和页面重复弹出同一错误；其他请求保留默认提示行为。</li></ul><p class="notice">'+str(tests['total_tests'])+' 项相关后端回归通过，包含5项新增恢复核对及并发变化边界；6个前端模板及恢复窗口/错误提示逻辑检查通过；本次原单页面验收7项通过。没有新增数据库结构，没有停止或释放另一张单据，也没有审核恢复原单。</p><h2>页面验收结果</h2><ol>'+''.join('<li>'+esc(x)+'</li>' for x in a['checks'])+'</ol><p class="muted">原额度及占用关系来自真实只读API。额度在提交前发生变化的响应通过浏览器拦截模拟，后台锁内重新校验由真实数据库事务回归验证。</p>']
 for name,title in [('01-exact-restore-gap.png','当前3件申请、1件余额及2件缺口，直接查看占用单据'),('02-concurrent-change-single-error.png','提交时额度变化：保留最新数量、禁用重复审核，窗口内仅一条错误')]:assert (OUT/name).is_file();parts.append('<h2>'+title+'</h2><a href="'+name+'"><img src="'+name+'" alt="'+title+'"></a>')
 parts.append('<h2>查询与库存复核</h2><p>'+str(len(q['checks']))+'项查询及库存核对通过，按本轮起止快照比较原业务与库存，没有新增仓库调用。</p><p class="muted">较早验收快照中的旧单CGT2180813128294803bfafea327ba2254b在15:13至15:18已有admin登记拒收、创建/撤回收回、继续申请记录，版本从5变化为8。此次保留这些既有变更，以本轮开始时状态作只读前后比较，没有回写旧单或旧快照。</p><h2>数据与仓库调用保持不变</h2><p>本单与占用单的业务状态、计划/实出/扣账数量、版本、执行、恢复申请以及SKU库存均在浏览器验收前后比较一致，仓库交互数量未增加。</p><details><summary>完整额度与验收证据</summary><pre>'+esc(json.dumps(a,ensure_ascii=False,indent=2))+'</pre></details><p><a href="/acceptance/purchase-return-fulfillment/验收报告.html">查看同CGT分次退仓完整验收报告</a></p></main></html>')
 (OUT/'验收报告.html').write_text(''.join(parts),'utf-8');dest=ROOT/'docker/local/dist/acceptance/purchase-return-restore-review';dest.mkdir(parents=True,exist_ok=True)
 for name in ['验收报告.html','acceptance.json','query-check.json','01-exact-restore-gap.png','02-concurrent-change-single-error.png']:shutil.copy2(OUT/name,dest/name)
 print('Report published: http://127.0.0.1:8088/acceptance/purchase-return-restore-review/验收报告.html')

if __name__=='__main__':main()
